      clearTimeout(timer);
    }
    if (isPressDown()) {
      timer = setTimeout(stop, STRAY_PRESS_MS);
      return;
    }
    const wait = clickUntil - now();
    if (wait > 0) {
      timer = setTimeout(stop, wait);
    } else {
      stop();
    }
