  const liftJudges = shadows.map(({root: shadow, host}, index) => ({
    shadow,
    host,
    handleRootUp: judgeUpUnlessBelow(
      index === 0 ? null : shadows[index - 1].host,
    ) as EventListener,
    handleHostUp: judgeUpUnlessBelow(null) as EventListener,
  }));
