  doc: Document,
  callback: () => void,
): void {
  if (!anyInFlight(doc)) {
    callback();
    return;
  }
  const callbacks = settledCallbacksByDocument.get(doc);
  if (callbacks == null) {
    settledCallbacksByDocument.set(doc, [callback]);
