function announceInModalRouted(
  dialog: HTMLDialogElement,
  message: string,
  politeness: AnnouncePoliteness = 'polite',
): WithdrawAnnouncement | null {
  if (!isExposed(dialog)) {
    return deliverBeyond(dialog, message, politeness);
