    key === undefined
      ? leafOrGroup
      : (leafOrGroup as Record<string, unknown>)[key];
  const role =
    key === undefined
      ? motionRoleOf(leafOrGroup)
      : motionRoleIn(leafOrGroup, key);
  if (role == null || role.kind === 'curve' || FIXED_ROLES.has(role.id)) {
    return value;
