  // arguments.
  const read = (roots: ShadowRoot[]): StaticRange[] | null => {
    try {
      return query.call(selection, {shadowRoots: roots});
    } catch {
      try {
        return (query as (...roots: ShadowRoot[]) => StaticRange[]).call(
          selection,
          ...roots,
        );
      } catch {
        return null;
      }
